// TEMP probe (#289 PR-2): capture the MULTI-SELECT AskUserQuestion screen shape
// — [ ]/[✔] checkboxes, the cursor, Space-toggle behavior, and the Submit button
// — so the new detectAskUserQuestion parser can read them. Throwaway.
import pty from 'node-pty'
import xterm from '@xterm/headless'
const { Terminal } = xterm
const CLAUDE = '/Users/juliusolsson/.local/bin/claude'
const CWD = '/Users/juliusolsson/Desktop/Development/agent-code'
const COLS = 120, ROWS = 50
const env = { ...process.env, TERM: 'xterm-256color', COLORTERM: 'truecolor', CLAUDE_CODE_ENTRYPOINT: 'claude-desktop' }
const term = new Terminal({ cols: COLS, rows: ROWS, allowProposedApi: true })
const p = pty.spawn(CLAUDE, [], { name: 'xterm-256color', cols: COLS, rows: ROWS, cwd: CWD, env })
p.onData(d => term.write(d))
const sleep = ms => new Promise(r => setTimeout(r, ms))
function screen() { const b = term.buffer.active, out = []; for (let i = 0; i < ROWS; i++) { const ln = b.getLine(b.baseY + i); out.push(ln ? ln.translateToString(true).replace(/\s+$/, '') : '') } return out.join('\n').replace(/\n{3,}/g, '\n\n') }
async function waitFor(pred, ms, label) { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (pred(screen())) return true; await sleep(150) } console.log(`[probe] TIMEOUT ${label}`); return false }
const isPicker = s => /to navigate · (Esc to cancel|Tab)|Enter to select|Space to (select|toggle)|to submit/i.test(s)
function dump(tag) { console.log(`\n========== ${tag} ==========\n${screen()}`) }
;(async () => {
  console.log('[probe] spawned; waiting for startup…')
  await waitFor(s => /❯|shortcuts|Welcome|Try "/.test(s), 30000, 'startup')
  if (/Do you trust|trust the files/i.test(screen())) { p.write('\r'); await sleep(1500) }
  await sleep(1500)
  const prompt = 'Use the AskUserQuestion tool RIGHT NOW to ask me ONE question where I can select MULTIPLE options (set multiSelect true). The options are: Red, Green, Blue, Yellow. Call the tool immediately as your first action and say nothing before it.'
  p.write(prompt); await sleep(400); p.write('\r')
  if (!(await waitFor(isPicker, 90000, 'multi-select picker'))) { p.kill(); return }
  await sleep(500)
  dump('MULTI-SELECT PICKER (initial)')
  // Toggle the focused option with Space, then move + toggle another, then go to Submit.
  const steps = [['SPACE (toggle)', ' '], ['DOWN', '\x1b[B'], ['SPACE (toggle)', ' '], ['DOWN', '\x1b[B'], ['DOWN', '\x1b[B'], ['DOWN', '\x1b[B']]
  for (const [name, key] of steps) { p.write(key); await sleep(500); dump(`after ${name}`) }
  console.log('\n[probe] Esc to cancel, exit (non-destructive).')
  p.write('\x1b'); await sleep(800); p.kill(); await sleep(300); process.exit(0)
})().catch(e => { console.error('[probe] error', e); p.kill(); process.exit(1) })

